import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Custom CUDA kernel for element-wise addition (reused) ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Custom CUDA kernel for transposed 2D convolution (naive) ----------
transposed_conv_kernel.cu = """
__global__ void transposed_convolution_kernel(
    const float* input,      // [B, C_in, H_in, W_in]
    const float* weight,     // [C_out, C_in, K_h, K_w]
    float* output,           // [B, C_out, H_out + O_p_h, W_out + O_p_w]
    int B,                  // batch size
    int C_in,               // in_channels
    int H_in,               // input height
    int W_in,               // input width
    int K_h,                // kernel height
    int K_w,                // kernel width
    int S_h,                // stride height
    int S_w,                // stride width
    int P_h,                // padding (input side)
    int P_w,                // padding (input side)
    int O_p_h,              // output padding top
    int O_p_w,              // output padding left
    int D_h,                // dilation height
    int D_w,                // dilation width
    int groups,
    bool bias) {

    // Compute output spatial dimensions:
    int H_out = (H_in * S_h + 2*P_h - K_h*(D_h-1)) / D_h + O_p_h;
    int W_out = (W_in * S_w + 2*P_w - K_w*(D_w-1)) / D_w + O_p_w;

    float* out_ptr = output.data_ptr<float>();

    const int block_size = 256;
    const int num_blocks_h = (H_out + block_size - 1) / block_size;
    const int num_blocks_w = (W_out + block_size - 1) / block_size;

    // Total threads: B * C_in * H_out * W_out
    const int total_threads = B * C_in * H_out * W_out;

    transposed_convolution_kernel<<<total_threads / block_size, block_size, 0>>>(
        input,
        weight,
        out_ptr,
        B, C_in, H_in, W_in, K_h, K_w, S_h, S_w, P_h, P_w, O_p_h, O_p_w,
        D_h, D_w, groups, bias
    );

    return output;
}
"""

transposed_conv_cuda_source = transposed_conv_kernel.cu

transposed_conv = load_inline(
    name="conv_transpose2d_cuda",
    cpp_sources=(
        "torch::Tensor conv_transpose2d_cuda(torch::Tensor x, int in_channels, int out_channels, "
        "std::array<int,2> kernel_size, std::array<int,2> stride, "
        "std::array<int,2> padding, int dilation, int groups, bool bias);"
    ),
    cuda_sources=transposed_conv_cuda_source,
    functions=["conv_transpose2d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super(ModelNew, self).__init__()
        # Store the custom transposed convolution operator
        self.conv_transpose2d_cuda = transposed_conv

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed 2D convolution using custom CUDA operator.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height_in, width_in).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, height_out, width_out).
        """
        return self.conv_transpose2d_cuda(x)
